// Page 01 / Cover — 国内电商进入存量博弈，公私域协同成增长主命题
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: '263442',    // 深藏青
    accent1: 'B44626',    // 铁锈橘
    accent2: '5A6675',    // 钢灰
    light:   'F7F6F3',    // 米白
    ink:     '242830',    // 墨黑
    muted:   '9AA3AE',    // 灰蓝（深底上调亮）
    line:    'DEDCD6',
  };

  const s = pptx.addSlide();
  s.background = { color: t.primary };

  // 顶部细线 accent2
  s.addShape('rect', { x: 0.6, y: 1.05, w: 0.7, h: 0.06, fill: { color: t.accent2 } });

  // 顶部小标
  s.addText('2026 Q3  ·  内部研究报告', {
    x: 0.6, y: 1.18, w: 8, h: 0.4,
    fontFace: 'PingFang SC', fontSize: 11, color: t.muted, charSpacing: 4,
  });

  // 顶部右上角小标签
  s.addShape('rect', {
    x: 11.6, y: 1.1, w: 1.15, h: 0.42,
    fill: { color: t.accent1 }, line: { type: 'none' },
  });
  s.addText('存量博弈期', {
    x: 11.6, y: 1.1, w: 1.15, h: 0.42,
    fontFace: 'PingFang SC', fontSize: 10, color: 'FFFFFF',
    align: 'center', valign: 'middle', bold: true, charSpacing: 2,
  });

  // 主标题 行 1
  s.addText('国内电商进入', {
    x: 0.6, y: 1.95, w: 12, h: 1.05,
    fontFace: 'PingFang SC', fontSize: 46, color: 'FFFFFF', bold: true,
    charSpacing: 2,
  });

  // 主标题 行 2（带 accent1 强调）
  s.addText([
    { text: '存量博弈', options: { color: t.accent1 } },
    { text: '，', options: { color: 'FFFFFF' } },
    { text: '公私域协同', options: { color: 'FFFFFF' } },
  ], {
    x: 0.6, y: 2.95, w: 12, h: 1.05,
    fontFace: 'PingFang SC', fontSize: 46, bold: true, charSpacing: 2,
  });

  // 主标题 行 3
  s.addText('成为增长主命题', {
    x: 0.6, y: 3.95, w: 12, h: 1.05,
    fontFace: 'PingFang SC', fontSize: 46, color: 'FFFFFF', bold: true,
    charSpacing: 2,
  });

  // 英文小标
  s.addText('CHINA  E-COMMERCE  TRAFFIC  LANDSCAPE  ·  PUBLIC-PRIVATE  DOMAIN  PLAYBOOK', {
    x: 0.6, y: 5.05, w: 12, h: 0.4,
    fontFace: 'Arial', fontSize: 11, color: t.accent2, charSpacing: 3,
  });

  // 三个核心数字横排
  const stats = [
    { num: '12.8亿', label: '全网 MAU（同比仅 +1.2%）' },
    { num: '620元',  label: '公域获客成本（三年 +63%）' },
    { num: '18×',    label: '公私域获客成本差距' },
  ];
  stats.forEach((it, i) => {
    const x = 0.6 + i * 4.2;
    s.addText(it.num, {
      x, y: 5.75, w: 4, h: 0.55,
      fontFace: 'Arial', fontSize: 26, color: 'FFFFFF', bold: true, charSpacing: 1,
    });
    s.addText(it.label, {
      x, y: 6.3, w: 4, h: 0.35,
      fontFace: 'PingFang SC', fontSize: 10, color: t.muted,
    });
    if (i < stats.length - 1) {
      s.addShape('rect', { x: x + 4.0 - 0.02, y: 5.85, w: 0.02, h: 0.7, fill: { color: '3D4A5A' } });
    }
  });

  // 底部信息
  s.addText('面向品牌商家决策层  ·  整理自 QuestMobile / 艾瑞 / TMO / 雪球 等公开口径', {
    x: 0.6, y: 7.0, w: 12, h: 0.3,
    fontFace: 'PingFang SC', fontSize: 9, color: t.muted,
  });

  // 底部 accent1 横条
  s.addShape('rect', { x: 0, y: 7.38, w: 13.33, h: 0.12, fill: { color: t.accent1 }, line: { type: 'none' } });

  return s;
}

// Page 02 / Summary — 五大核心判断：存量博弈期的电商新规则
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: '263442', accent1: 'B44626', accent2: '5A6675',
    light: 'F7F6F3', ink: '242830', muted: '626773', line: 'DEDCD6',
  };

  const s = pptx.addSlide();
  s.background = { color: 'FFFFFF' };

  // 顶部色条
  s.addShape('rect', { x: 0, y: 0, w: 13.33, h: 0.5, fill: { color: t.primary }, line: { type: 'none' } });

  // 顶部 EN 标签
  s.addText('EXECUTIVE  SUMMARY', {
    x: 0.6, y: 0.06, w: 6, h: 0.4,
    fontFace: 'Arial', fontSize: 10, color: t.accent1, bold: true, charSpacing: 4,
  });
  s.addText('汇报摘要 / 五条核心判断', {
    x: 6.6, y: 0.06, w: 6.2, h: 0.4,
    fontFace: 'PingFang SC', fontSize: 10, color: 'FFFFFF', align: 'right',
  });

  // 大标题
  s.addText('五大核心判断', {
    x: 0.6, y: 0.85, w: 8, h: 0.7,
    fontFace: 'PingFang SC', fontSize: 30, color: t.primary, bold: true,
  });
  s.addText('存量博弈期的电商新规则', {
    x: 0.6, y: 1.55, w: 8, h: 0.5,
    fontFace: 'PingFang SC', fontSize: 17, color: t.accent2,
  });

  // 右上角小标签
  s.addText('2026 Q3', {
    x: 11.5, y: 1.0, w: 1.3, h: 0.4,
    fontFace: 'Arial', fontSize: 12, color: t.muted, align: 'right',
  });
  s.addShape('rect', { x: 12.5, y: 1.42, w: 0.3, h: 0.04, fill: { color: t.accent1 } });

  // 5 张判断卡片（横排）
  const items = [
    {
      no: '01', title: '流量见顶',
      lead: '进入存量博弈',
      data: '12.82 亿',
      caption: '全网 MAU，同比仅 +1.2%',
      desc: '短视频渗透 92.6%，拉新红利基本耗尽',
    },
    {
      no: '02', title: '获客飞涨',
      lead: '单次 ROI 持续走低',
      data: '620 元/人',
      caption: '综合获客成本，三年 +63%',
      desc: '2020 年 1:5 的投放公式，2025 年仅剩 1:1.5',
    },
    {
      no: '03', title: '成本剪刀差',
      lead: '私域是利润源',
      data: '18×',
      caption: '公私域获客成本差距',
      desc: '私域成熟商家 30–60 元 / 人，复购 3.2 倍、转介绍 4.7 倍',
    },
    {
      no: '04', title: '微信小店',
      lead: '增长最大变量',
      data: '+225%',
      caption: '视频号电商 GMV 同比',
      desc: 'DAU 约 8 亿、送礼物 / 一起买 / 点赞买打通社交闭环',
    },
    {
      no: '05', title: '范式切换',
      lead: '买流量 → 经营用户资产',
      data: '飞轮',
      caption: '公域捞鱼、私域养鱼、反哺公域',
      desc: '先跑通最小闭环，再规模化放大',
    },
  ];

  const cardW = 2.4, cardH = 4.6, gap = 0.12, startX = 0.6, startY = 2.3;
  items.forEach((it, i) => {
    const x = startX + i * (cardW + gap);

    // 卡片底
    s.addShape('rect', {
      x, y: startY, w: cardW, h: cardH,
      fill: { color: t.light }, line: { color: t.line, width: 0.75 },
    });
    // 顶部 accent1 边条
    s.addShape('rect', {
      x, y: startY, w: cardW, h: 0.08,
      fill: { color: t.accent1 }, line: { type: 'none' },
    });

    // 大编号
    s.addText(it.no, {
      x: x + 0.15, y: startY + 0.18, w: cardW - 0.3, h: 0.6,
      fontFace: 'Arial', fontSize: 26, color: t.accent1, bold: true, charSpacing: 1,
    });

    // 标题
    s.addText(it.title, {
      x: x + 0.15, y: startY + 0.78, w: cardW - 0.3, h: 0.45,
      fontFace: 'PingFang SC', fontSize: 15, color: t.primary, bold: true,
    });

    // lead
    s.addText(it.lead, {
      x: x + 0.15, y: startY + 1.22, w: cardW - 0.3, h: 0.4,
      fontFace: 'PingFang SC', fontSize: 11, color: t.accent2,
    });

    // 分隔线
    s.addShape('rect', {
      x: x + 0.15, y: startY + 1.75, w: 0.6, h: 0.02,
      fill: { color: t.primary }, line: { type: 'none' },
    });

    // 大数字
    s.addText(it.data, {
      x: x + 0.15, y: startY + 1.95, w: cardW - 0.3, h: 0.7,
      fontFace: 'Arial', fontSize: 28, color: t.primary, bold: true, charSpacing: 1,
    });
    // 数据注脚
    s.addText(it.caption, {
      x: x + 0.15, y: startY + 2.7, w: cardW - 0.3, h: 0.45,
      fontFace: 'PingFang SC', fontSize: 10, color: t.muted,
    });

    // 描述
    s.addShape('rect', {
      x: x + 0.15, y: startY + 3.25, w: cardW - 0.3, h: 0.02,
      fill: { color: t.line }, line: { type: 'none' },
    });
    s.addText(it.desc, {
      x: x + 0.15, y: startY + 3.32, w: cardW - 0.3, h: 1.2,
      fontFace: 'PingFang SC', fontSize: 10, color: t.ink, lineSpacingMultiple: 1.3,
    });
  });

  // 底部核心结论条
  s.addShape('rect', {
    x: 0.6, y: 7.05, w: 12.13, h: 0.32,
    fill: { color: t.primary }, line: { type: 'none' },
  });
  s.addText('核心结论：公域决定增长下限（新客规模），私域决定增长上限（LTV 与利润），公私域飞轮转速决定胜率。', {
    x: 0.7, y: 7.05, w: 12.0, h: 0.32,
    fontFace: 'PingFang SC', fontSize: 11, color: 'FFFFFF', valign: 'middle',
  });

  // 页码徽章
  s.addShape('ellipse', { x: 12.55, y: 6.95, w: 0.38, h: 0.38, fill: { color: t.accent1 } });
  s.addText('02', {
    x: 12.55, y: 6.95, w: 0.38, h: 0.38,
    fontFace: 'Arial', fontSize: 10, color: 'FFFFFF', align: 'center', valign: 'middle', bold: true,
  });

  return s;
}

// Page 03 / Metrics Overview — 大盘见顶：用户触顶、获客成本三年涨 63%
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: '263442', accent1: 'B44626', accent2: '5A6675',
    light: 'F7F6F3', ink: '242830', muted: '626773', line: 'DEDCD6',
  };

  const s = pptx.addSlide();
  s.background = { color: 'FFFFFF' };

  // 顶部小标
  s.addShape('rect', { x: 0.6, y: 0.55, w: 0.7, h: 0.06, fill: { color: t.accent1 } });
  s.addText('01  ·  TRAFFIC  OVERVIEW', {
    x: 0.6, y: 0.7, w: 8, h: 0.35,
    fontFace: 'Arial', fontSize: 10, color: t.accent2, bold: true, charSpacing: 4,
  });

  // 大标题
  s.addText('大盘见顶：从拉新红利到存量博弈', {
    x: 0.6, y: 1.1, w: 12, h: 0.7,
    fontFace: 'PingFang SC', fontSize: 28, color: t.primary, bold: true,
  });
  s.addText('用户规模触顶，平台与商家同时进入零和博弈', {
    x: 0.6, y: 1.85, w: 12, h: 0.45,
    fontFace: 'PingFang SC', fontSize: 14, color: t.accent2,
  });

  // 3 张 KPI 卡
  const kpis = [
    {
      label: '全网 MAU',
      big: '12.82',
      unit: '亿',
      delta: '同比 +1.2%',
      deltaType: 'neutral',
      sub: '2026 年 6 月，互联网用户规模触顶',
      tag: '用户见顶',
    },
    {
      label: '综合获客成本（CAC）',
      big: '620',
      unit: '元/人',
      delta: '三年 +63%',
      deltaType: 'up',
      sub: '2023 年 380 元 → 2026Q1 620 元',
      tag: '成本上行',
    },
    {
      label: '投放 ROI',
      big: '1 : 1.5',
      unit: '',
      delta: 'vs 2020 年 1 : 5',
      deltaType: 'down',
      sub: '爆款公式失效，5 倍杠杆消失',
      tag: 'ROI 跌穿',
    },
  ];

  const cardW = 3.95, cardH = 2.6, gap = 0.2, startX = 0.6, startY = 2.55;
  kpis.forEach((k, i) => {
    const x = startX + i * (cardW + gap);
    // 卡底
    s.addShape('rect', {
      x, y: startY, w: cardW, h: cardH,
      fill: { color: t.light }, line: { color: t.line, width: 0.75 },
    });
    // 左侧 accent 边条
    s.addShape('rect', {
      x, y: startY, w: 0.08, h: cardH,
      fill: { color: t.accent1 }, line: { type: 'none' },
    });

    // 标签
    s.addText(k.label, {
      x: x + 0.3, y: startY + 0.25, w: cardW - 0.5, h: 0.35,
      fontFace: 'PingFang SC', fontSize: 12, color: t.muted, charSpacing: 1,
    });

    // 大数字 + 单位
    s.addText([
        { text: k.big, options: { fontFace: 'Arial', fontSize: 48, color: t.primary, bold: true, charSpacing: 1 } },
        { text: '  ' + k.unit, options: { fontFace: 'PingFang SC', fontSize: 16, color: t.primary } },
      ], {
        x: x + 0.3, y: startY + 0.6, w: cardW - 0.5, h: 1.0,
      });

    // 同比徽章
    const deltaColor = k.deltaType === 'up' ? t.accent1 : (k.deltaType === 'down' ? t.primary : t.accent2);
    s.addShape('rect', {
      x: x + 0.3, y: startY + 1.65, w: 1.6, h: 0.32,
      fill: { color: k.deltaType === 'down' ? t.primary : t.accent1 }, line: { type: 'none' },
    });
    s.addText(k.delta, {
      x: x + 0.3, y: startY + 1.65, w: 1.6, h: 0.32,
      fontFace: 'PingFang SC', fontSize: 10, color: 'FFFFFF', bold: true,
      align: 'center', valign: 'middle',
    });

    // 副文字
    s.addText(k.sub, {
      x: x + 0.3, y: startY + 2.05, w: cardW - 0.5, h: 0.45,
      fontFace: 'PingFang SC', fontSize: 10, color: t.ink, lineSpacingMultiple: 1.3,
    });

    // 标签在右下
    s.addText(k.tag, {
      x: x + cardW - 1.05, y: startY + 1.7, w: 0.95, h: 0.3,
      fontFace: 'PingFang SC', fontSize: 9, color: t.muted, align: 'right',
    });
  });

  // 下方 3 个亮点小条
  const facts = [
    { tag: '渗透率', val: '92.6%', desc: '短视频行业活跃渗透率（2026Q2）' },
    { tag: '从业者', val: '−12.5%', desc: '截至 2025 年 6 月电商从业者同比' },
    { tag: '商家数', val: '−18.3%', desc: '淘宝活跃商家数量同比下降' },
  ];
  const fW = 3.95, fH = 1.05, fGap = 0.2, fY = 5.4;
  facts.forEach((f, i) => {
    const x = 0.6 + i * (fW + fGap);
    s.addShape('rect', {
      x, y: fY, w: fW, h: fH,
      fill: { color: 'FFFFFF' }, line: { color: t.line, width: 0.75 },
    });
    s.addShape('rect', {
      x, y: fY, w: 0.08, h: fH,
      fill: { color: t.primary }, line: { type: 'none' },
    });
    s.addText(f.tag, {
      x: x + 0.25, y: fY + 0.15, w: 1.4, h: 0.3,
      fontFace: 'PingFang SC', fontSize: 10, color: t.muted,
    });
    s.addText(f.val, {
      x: x + 0.25, y: fY + 0.4, w: 1.6, h: 0.5,
      fontFace: 'Arial', fontSize: 22, color: t.primary, bold: true,
    });
    s.addText(f.desc, {
      x: x + 1.9, y: fY + 0.2, w: fW - 2.05, h: 0.7,
      fontFace: 'PingFang SC', fontSize: 10, color: t.ink, valign: 'middle', lineSpacingMultiple: 1.3,
    });
  });

  // 底部洞察条
  s.addShape('rect', {
    x: 0.6, y: 6.7, w: 12.13, h: 0.4,
    fill: { color: t.primary }, line: { type: 'none' },
  });
  s.addText('结论：平台之间争抢用户时长与钱包份额，商家之间争抢经营效率与用户资产——单次 ROI 持续走低已成必然。', {
    x: 0.7, y: 6.7, w: 12.0, h: 0.4,
    fontFace: 'PingFang SC', fontSize: 11, color: 'FFFFFF', valign: 'middle',
  });

  // 页码徽章
  s.addShape('ellipse', { x: 12.55, y: 7.18, w: 0.3, h: 0.3, fill: { color: t.accent1 } });
  s.addText('03', {
    x: 12.55, y: 7.18, w: 0.3, h: 0.3,
    fontFace: 'Arial', fontSize: 9, color: 'FFFFFF', align: 'center', valign: 'middle', bold: true,
  });

  return s;
}

