        align: 'center', valign: 'middle',
      });
    }
  });

  // 关键数据（3 条）
  const dStats = [
    { v: '4 万亿',  k: '2025 抖音电商 GMV' },
    { v: '51%',    k: '品牌自播占比（已超达人）' },
