  const wxPath = ['公域获新', '小店成交', '私域沉淀', '复购裂变'];
  const wpW = (rw - 0.5) / 4 - 0.05;
  wxPath.forEach((p, i) => {
    const x = rx + 0.25 + i * (wpW + 0.05);
    s.addShape('rect', {
      x, y: ry + 1.65, w: wpW, h: 0.32,
