    s.addText(d.v, {
      x: x + 0.1, y: ry + 2.25, w: (rw - 0.5) / 3 - 0.25, h: 0.4,
      fontFace: 'Arial', fontSize: 18, color: t.accent1, bold: true,
    });
    s.addText(d.k, {
      x: x + 0.1, y: ry + 2.65, w: (rw - 0.5) / 3 - 0.25, h: 0.3,
      fontFace: 'PingFang SC', fontSize: 8, color: t.muted,
