// 把 page_XX.mjs 中的 addShape/addText 调用提取出来，按 1280×720 比例生成同名 .html 预览
// 读源码 → 解析关键 addText/addShape/addImage → 输出 HTML
import fs from 'node:fs';
import path from 'node:path';

const PAGES_DIR = path.resolve('./pages');
const OUT_DIR = PAGES_DIR;

// 13.33in × 7.5in → 1280 × 720，比例约 96 px/inch
const SCALE = 96;

const theme = {
  '263442': '#263442',
  'B44626': '#b44626',
  '5A6675': '#5a6675',
  'F7F6F3': '#f7f6f3',
  '242830': '#242830',
  '9AA3AE': '#9aa3ae',
  '626773': '#626773',
  'DEDCD6': '#dedcd6',
  'FFFFFF': '#ffffff',
  'F4D9CD': '#f4d9cd',
  '3D4A5A': '#3d4a5a',
};

function colorToCss(c) {
  if (!c) return 'transparent';
  return theme[c] || `#${c.toLowerCase()}`;
}

function hexToRgba(hex, alpha) {
  const h = (theme[hex] || `#${hex}`).replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

// 简易 .mjs 解析：匹配 s.addText('content', opts) 与 s.addShape('type', opts)
function parseMjs(src) {
  const shapes = [];
  const texts = [];

  // 匹配 addShape('rect'|'ellipse', { ... }); 加换行处理嵌套括号
  const shapeRe = /s\.addShape\(\s*'([^']+)'\s*,\s*\{([\s\S]*?)\}\s*\)/g;
  let m;
  while ((m = shapeRe.exec(src)) !== null) {
    const type = m[1];
    const body = m[2];
    const obj = parseObj(body);
    shapes.push({ type, ...obj });
  }

  // 匹配 s.addText('text', opts)
  const textRe = /s\.addText\(\s*('[\s\S]*?')(?:,\s*\{([\s\S]*?)\})?\s*\)/g;
  while ((m = textRe.exec(src)) !== null) {
    const rawStr = m[1];
    const body = m[2] || '';
    const obj = parseObj(body);
    // 解码字符串字面量（去掉外层单引号）
    let str = rawStr;
    if (str.startsWith("'") && str.endsWith("'")) str = str.slice(1, -1);
    str = str.replace(/\\n/g, ' ').replace(/\s+/g, ' ').trim();
    texts.push({ str, ...obj });
  }

  // 匹配 s.addText([{text:'a', options:{...}}, ...], opts)
  const arrRe = /s\.addText\(\s*\[([\s\S]*?)\]\s*,\s*\{([\s\S]*?)\}\s*\)/g;
  while ((m = arrRe.exec(src)) !== null) {
    const arrBody = m[1];
    const optsBody = m[2];
    const obj = parseObj(optsBody);
    const parts = [];
    const itemRe = /\{\s*text:\s*('[\s\S]*?')(?:,\s*options:\s*\{([\s\S]*?)\})?\s*\}/g;
    let im;
    while ((im = itemRe.exec(arrBody)) !== null) {
      let t = im[1];
      if (t.startsWith("'") && t.endsWith("'")) t = t.slice(1, -1);
      t = t.replace(/\\n/g, ' ').replace(/\s+/g, ' ').trim();
      const optObj = im[2] ? parseObj(im[2]) : {};
      parts.push({ text: t, options: optObj });
    }
    if (parts.length) texts.push({ str: '__RICH__', parts, ...obj });
  }

  return { shapes, texts };
}

function parseObj(body) {
  const obj = {};
  // 简单键值对解析：key: value，支持字符串/数字/对象
  const keyRe = /(\w+):\s*('([^']*)'|"([^"]*)"|(\{[\s\S]*?\})|(\[[\s\S]*?\])|(-?\d*\.?\d+)|true|false/g;
  // 简单分割：按逗号，但跳过嵌套括号/字符串
  const tokens = splitTopLevel(body, ',');
  for (const tk of tokens) {
    const colonIdx = tk.indexOf(':');
    if (colonIdx === -1) continue;
    const key = tk.slice(0, colonIdx).trim();
    let val = tk.slice(colonIdx + 1).trim();
    obj[key] = parseVal(val);
  }
  return obj;
}

function splitTopLevel(s, sep) {
  const out = [];
  let depth = 0, inStr = false, strCh = '', last = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (c === strCh && s[i - 1] !== '\\') { inStr = false; }
    } else {
      if (c === "'" || c === '"') { inStr = true; strCh = c; }
      else if (c === '{' || c === '[' || c === '(') depth++;
      else if (c === '}' || c === ']' || c === ')') depth--;
      else if (c === sep && depth === 0) {
        out.push(s.slice(last, i));
        last = i + 1;
      }
    }
  }
  out.push(s.slice(last));
  return out.map((x) => x.trim()).filter(Boolean);
}

function parseVal(v) {
  if (v === 'true') return true;
  if (v === 'false') return false;
  if (v === 'none' || v === undefined || v === null) return null;
  if (/^-?\d*\.?\d+$/.test(v)) return Number(v);
  if ((v.startsWith("'") && v.endsWith("'")) || (v.startsWith('"') && v.endsWith('"'))) {
    return v.slice(1, -1);
  }
  if (v.startsWith('{') && v.endsWith('}')) {
    return parseObj(v.slice(1, -1));
  }
  return v;
}

function esc(s) {
  return String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}

function renderShape(s) {
  if (s.type === 'rect') {
    const fill = s.fill && s.fill.color ? colorToCss(s.fill.color) : 'transparent';
    const line = s.line && s.line.color ? `1px solid ${colorToCss(s.line.color)}` : 'none';
    const left = (s.x || 0) * SCALE;
    const top = (s.y || 0) * SCALE;
    const w = (s.w || 0) * SCALE;
    const h = (s.h || 0) * SCALE;
    return `<div style="position:absolute;left:${left}px;top:${top}px;width:${w}px;height:${h}px;background:${fill};${line !== 'none' ? `border:${line};` : ''}"></div>`;
  }
  if (s.type === 'ellipse') {
    const fill = s.fill && s.fill.color ? colorToCss(s.fill.color) : 'transparent';
    const left = (s.x || 0) * SCALE;
    const top = (s.y || 0) * SCALE;
    const w = (s.w || 0) * SCALE;
    const h = (s.h || 0) * SCALE;
    return `<div style="position:absolute;left:${left}px;top:${top}px;width:${w}px;height:${h}px;background:${fill};border-radius:50%"></div>`;
  }
  return '';
}

function renderText(t) {
  const left = (t.x || 0) * SCALE;
  const top = (t.y || 0) * SCALE;
  const w = (t.w || 0) * SCALE;
  const h = (t.h || 0) * SCALE;
  let color = '#242830';
  if (t.color) color = colorToCss(t.color);
  else if (t.color === null) color = 'transparent';
  const fontSize = t.fontSize || 12;
  const bold = t.bold ? '700' : '400';
  const align = t.align || 'left';
  const valign = t.valign || 'top';
  const charSpacing = t.charSpacing ? `${t.charSpacing / 100}em` : 'normal';
  const lineHeight = t.lineSpacingMultiple || 1.3;

  let content = '';
  if (t.parts && t.str === '__RICH__') {
    content = t.parts.map((p) => {
      let c = '#242830';
      if (p.options && p.options.color) c = colorToCss(p.options.color);
      const b = (p.options && p.options.bold) ? '700' : '400';
      return `<span style="color:${c};font-weight:${b}">${esc(p.text)}</span>`;
    }).join('');
  } else {
    content = esc(t.str || '');
  }

  return `<div style="position:absolute;left:${left}px;top:${top}px;width:${w}px;height:${h}px;font-size:${fontSize}px;color:${color};font-weight:${bold};text-align:${align};vertical-align:${valign};letter-spacing:${charSpacing};line-height:${lineHeight};font-family:'PingFang SC','Microsoft YaHei',Arial,sans-serif;white-space:pre-wrap;overflow:hidden;box-sizing:border-box">${content}</div>`;
}

function buildHtml(filename, pageNum) {
  const src = fs.readFileSync(path.join(PAGES_DIR, filename), 'utf8');
  const { shapes, texts } = parseMjs(src);

  // 找背景色
  const bgMatch = src.match(/s\.background\s*=\s*\{\s*color:\s*'([0-9A-Fa-f]+)'\s*\}/);
  const bg = bgMatch ? colorToCss(bgMatch[1]) : '#ffffff';

  const layer = shapes.map(renderShape).join('\n') + '\n' + texts.map(renderText).join('\n');

  return `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8">
<title>${filename}</title>
<style>
  body { margin: 0; background: #f0f1f3; font-family: -apple-system, 'Segoe UI', sans-serif; }
  .stage { position: relative; width: 1280px; height: 720px; background: ${bg}; margin: 20px auto; box-shadow: 0 4px 24px rgba(0,0,0,0.15); overflow: hidden; }
  .label { position: fixed; top: 10px; right: 12px; font-size: 11px; color: #888; background: rgba(255,255,255,0.85); padding: 3px 9px; border-radius: 4px; border: 1px solid #dedcd6; }
</style>
</head>
<body>
<div class="label">agent HTML · ${filename} · p${pageNum}/9</div>
<div class="stage">
${layer}
</div>
</body></html>`;
}

const files = fs.readdirSync(PAGES_DIR).filter((f) => /^page_\d{2}\.mjs$/.test(f)).sort();
for (const f of files) {
  const num = parseInt(f.match(/page_(\d{2})/)[1], 10);
  const html = buildHtml(f, num);
  const outPath = path.join(OUT_DIR, f.replace('.mjs', '.html'));
  fs.writeFileSync(outPath, html);
  console.log(`OK · ${outPath}`);
}

