// 把 page_XX.mjs 中的 addShape/addText 调用提取出来，按 1280×720 比例生成同名 .html 预览
// 改进：用位置遍历 + 括号平衡，避免正则贪婪/闭合冲突
import fs from 'node:fs';
import path from 'node:path';

const PAGES_DIR = path.resolve('./pages');

const SCALE = 96; // 13.33in × 7.5in → 1280 × 720

const theme = {
  '263442': '#263442',
  'B44626': '#b44626',
  '5A6675': '#5a6675',
  'F7F6F3': '#f7f6f3',
  '242830': '#242830',
  '9AA3AE': '#9aa3ae',
  '626773': '#626773',
  'DEDCD6': '#dedcd6',
  'FFFFFF': '#ffffff',
  'F4D9CD': '#f4d9cd',
  '3D4A5A': '#3d4a5a',
};

function colorToCss(c) {
  if (!c) return 'transparent';
  return theme[c] || `#${c.toLowerCase()}`;
}

// 找到 s.addText / s.addShape 调用的起止位置（含括号平衡）
function findCallRanges(src, fnName) {
  const ranges = [];
  const re = new RegExp(`s\\.${fnName}\\(`, 'g');
  let m;
  while ((m = re.exec(src)) !== null) {
    const start = m.index;
    // 从 start 后第一个 '(' 位置开始，向后找匹配的 ')'
    const openIdx = m.index + m[0].length - 1;
    let depth = 0, inStr = false, strCh = '', end = -1;
    for (let i = openIdx; i < src.length; i++) {
      const c = src[i];
      if (inStr) {
        if (c === '\\') { i++; continue; }
        if (c === strCh) inStr = false;
      } else {
        if (c === "'" || c === '"') { inStr = true; strCh = c; }
        else if (c === '(' || c === '[' || c === '{') depth++;
        else if (c === ')' || c === ']' || c === '}') {
          depth--;
          if (depth === 0 && c === ')') { end = i; break; }
        }
      }
    }
    if (end !== -1) ranges.push({ start, end, body: src.slice(openIdx + 1, end) });
  }
  return ranges;
}

// 切分顶层逗号（用于解析对象字面量参数）
function splitTopLevel(s, sep = ',') {
  const out = [];
  let depth = 0, inStr = false, strCh = '', last = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (c === '\\') { i++; continue; }
      if (c === strCh) inStr = false;
    } else {
      if (c === "'" || c === '"') { inStr = true; strCh = c; }
      else if (c === '{' || c === '[' || c === '(') depth++;
      else if (c === '}' || c === ']' || c === ')') depth--;
      else if (c === sep && depth === 0) {
        out.push(s.slice(last, i));
        last = i + 1;
      }
    }
  }
  out.push(s.slice(last));
  return out.map((x) => x.trim()).filter(Boolean);
}

function parseVal(v) {
  v = v.trim();
  if (v === 'true') return true;
  if (v === 'false') return false;
  if (v === 'none' || v === '' || v === 'null' || v === 'undefined') return null;
  if (/^-?\d*\.?\d+$/.test(v)) return Number(v);
  if ((v.startsWith("'") && v.endsWith("'")) || (v.startsWith('"') && v.endsWith('"'))) {
    return v.slice(1, -1);
  }
  if (v.startsWith('{') && v.endsWith('}')) {
    return parseObj(v.slice(1, -1));
  }
  if (v.startsWith('[') && v.endsWith(']')) {
    return v.slice(1, -1);
  }
  return v;
}

function parseObj(body) {
  const obj = {};
  const tokens = splitTopLevel(body, ',');
  for (const tk of tokens) {
    const colonIdx = findTopColon(tk);
    if (colonIdx === -1) continue;
    const key = tk.slice(0, colonIdx).trim();
    const val = tk.slice(colonIdx + 1).trim();
    obj[key] = parseVal(val);
  }
  return obj;
}

function findTopColon(s) {
  let depth = 0, inStr = false, strCh = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (c === '\\') { i++; continue; }
      if (c === strCh) inStr = false;
    } else {
      if (c === "'" || c === '"') { inStr = true; strCh = c; }
      else if (c === '{' || c === '[' || c === '(') depth++;
      else if (c === '}' || c === ']' || c === ')') depth--;
      else if (c === ':' && depth === 0) return i;
    }
  }
  return -1;
}

// 解析 addShape(type, opts) 调用
function parseShapeCall(body) {
  // 顶层两个参数：type(string), opts(object)
  const args = splitTopLevel(body, ',');
  const type = args[0].trim().replace(/^['"]|['"]$/g, '');
  const opts = args.length > 1 ? parseObj(args.slice(1).join(',')) : {};
  return { type, ...opts };
}

// 解析 addText 调用
function parseTextCall(body) {
  // 第一个参数要么是字符串字面量，要么是 rich text 数组
  const args = splitTopLevel(body, ',');
  const first = args[0].trim();
  const opts = args.length > 1 ? parseObj(args.slice(1).join(',')) : {};

  if (first.startsWith('[')) {
    // rich text：[{text:'...', options:{...}}, ...]
    const arr = first.slice(1, -1);
    const parts = [];
    const itemRe = /\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g; // 简易匹配一级对象
    let m;
    while ((m = itemRe.exec(arr)) !== null) {
      const inner = m[0].slice(1, -1);
      const itemObj = parseObj(inner);
      if (itemObj.text !== undefined) {
        parts.push({ text: String(itemObj.text), options: itemObj.options || {} });
      }
    }
    return { parts, ...opts };
  } else {
    // 简单字符串
    const str = first.replace(/^['"]|['"]$/g, '').replace(/\\n/g, '\n');
    return { str, ...opts };
  }
}

function esc(s) {
  return String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}

function renderShape(s) {
  if (s.type === 'rect' || !s.type) {
    const fill = s.fill && s.fill.color ? colorToCss(s.fill.color) : 'transparent';
    const line = s.line && s.line.color ? `1px solid ${colorToCss(s.line.color)}` : 'none';
    const left = (s.x || 0) * SCALE;
    const top = (s.y || 0) * SCALE;
    const w = (s.w || 0) * SCALE;
    const h = (s.h || 0) * SCALE;
    return `<div style="position:absolute;left:${left}px;top:${top}px;width:${w}px;height:${h}px;background:${fill};${line !== 'none' ? `border:${line};` : ''}"></div>`;
  }
  if (s.type === 'ellipse') {
    const fill = s.fill && s.fill.color ? colorToCss(s.fill.color) : 'transparent';
    const left = (s.x || 0) * SCALE;
    const top = (s.y || 0) * SCALE;
    const w = (s.w || 0) * SCALE;
    const h = (s.h || 0) * SCALE;
    return `<div style="position:absolute;left:${left}px;top:${top}px;width:${w}px;height:${h}px;background:${fill};border-radius:50%"></div>`;
  }
  return '';
}

function renderText(t) {
  const left = (t.x || 0) * SCALE;
  const top = (t.y || 0) * SCALE;
  const w = (t.w || 0) * SCALE;
  const h = (t.h || 0) * SCALE;
  const color = t.color ? colorToCss(t.color) : '#242830';
  const fontSize = t.fontSize || 12;
  const bold = t.bold ? '700' : '400';
  const align = t.align || 'left';
  const valign = t.valign || 'top';
  const charSpacing = t.charSpacing ? `${t.charSpacing / 100}em` : 'normal';
  const lineHeight = t.lineSpacingMultiple || 1.3;

  let content = '';
  if (t.parts) {
    content = t.parts.map((p) => {
      let c = '#242830';
      if (p.options && p.options.color) c = colorToCss(p.options.color);
      const b = (p.options && p.options.bold) ? '700' : '400';
      return `<span style="color:${c};font-weight:${b}">${esc(p.text)}</span>`;
    }).join('');
  } else {
    content = esc(t.str || '');
  }

  return `<div style="position:absolute;left:${left}px;top:${top}px;width:${w}px;height:${h}px;font-size:${fontSize}px;color:${color};font-weight:${bold};text-align:${align};vertical-align:${valign === 'middle' ? 'middle' : 'top'};letter-spacing:${charSpacing};line-height:${lineHeight};font-family:'PingFang SC','Microsoft YaHei',Arial,sans-serif;white-space:pre-wrap;overflow:hidden;box-sizing:border-box">${content}</div>`;
}

function buildHtml(filename, pageNum) {
  const src = fs.readFileSync(path.join(PAGES_DIR, filename), 'utf8');

  // 背景
  const bgMatch = src.match(/s\.background\s*=\s*\{\s*color:\s*'([0-9A-Fa-f]+)'\s*\}/);
  const bg = bgMatch ? colorToCss(bgMatch[1]) : '#ffffff';

  const shapeRanges = findCallRanges(src, 'addShape');
  const textRanges = findCallRanges(src, 'addText');

  const shapes = shapeRanges.map((r) => parseShapeCall(r.body));
  const texts = textRanges.map((r) => parseTextCall(r.body));

  const layer = shapes.map(renderShape).join('\n') + '\n' + texts.map(renderText).join('\n');

  return `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8">
<title>${filename}</title>
<style>
  body { margin: 0; background: #f0f1f3; font-family: -apple-system, 'Segoe UI', sans-serif; }
  .stage { position: relative; width: 1280px; height: 720px; background: ${bg}; margin: 20px auto; box-shadow: 0 4px 24px rgba(0,0,0,0.15); overflow: hidden; }
  .label { position: fixed; top: 10px; right: 12px; font-size: 11px; color: #888; background: rgba(255,255,255,0.85); padding: 3px 9px; border-radius: 4px; border: 1px solid #dedcd6; }
</style>
</head>
<body>
<div class="label">agent HTML · ${filename} · p${pageNum}/9</div>
<div class="stage">
${layer}
</div>
</body></html>`;
}

const files = fs.readdirSync(PAGES_DIR).filter((f) => /^page_\d{2}\.mjs$/.test(f)).sort();
for (const f of files) {
  const num = parseInt(f.match(/page_(\d{2})/)[1], 10);
  const html = buildHtml(f, num);
  const outPath = path.join(PAGES_DIR, f.replace('.mjs', '.html'));
  fs.writeFileSync(outPath, html);
  console.log(`OK · ${outPath}`);
}

